// RAPIDIO_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module RAPIDIO_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [31:0] c_cfg_dev_id_car,
  input logic [31:0] c_cfg_dev_info_car,
  input logic [31:0] c_cfg_asm_id_car,
  input logic [31:0] c_cfg_asm_info_car,
  input logic [31:0] c_cfg_pe_feat_car,
  input logic [23:0] c_cfg_base_id,
  input logic [9:0] c_host_addr,
  input logic [7:0] c_host_wdata,
  input logic [15:0] c_ob_dest,
  input logic [7:0] c_ob_tid,
  input logic  c_ob_tt,
  input logic [15:0] c_ob_info,
  input logic  c_id_load,
  input logic  c_host_wr,
  input logic  c_host_rd,
  input logic  c_ob_start,
  input logic [7:0] c_host_rdata,
  input logic [23:0] c_base_id,
  input logic  c_ob_busy,
  input logic  c_busy,
  input logic [2:0] c_rx_why,
  input logic [3:0] c_rx_ftype,
  input logic [15:0] c_db_info,
  input logic [7:0] c_db_tid,
  input logic [15:0] c_db_src,
  input logic [3:0] c_ob_status,
  input logic  c_rx_rep,
  input logic  c_db_valid,
  input logic  c_ob_done
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 23;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:22];          // model of every stored word
  logic [5:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;
  logic m_state_RX_REP;          // full / valid pulse / available
  logic m_state_DOORBELL;          // full / valid pulse / available
  logic m_state_OB_DONE;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_rx_rep && !m_state_RX_REP) m_set[0] = 1'b1;
    if (c_rx_rep && m_state_RX_REP && (m_rd && m_map && m_idx == 19)) m_set[0] = 1'b1;
    if (c_rx_rep && m_state_RX_REP && !(m_rd && m_map && m_idx == 19)) m_set[1] = 1'b1;
    if (c_db_valid && !m_state_DOORBELL) m_set[2] = 1'b1;
    if (c_db_valid && m_state_DOORBELL && (m_rd && m_map && m_idx == 21)) m_set[2] = 1'b1;
    if (c_db_valid && m_state_DOORBELL && !(m_rd && m_map && m_idx == 21)) m_set[3] = 1'b1;
    if (c_ob_done && !m_state_OB_DONE) m_set[4] = 1'b1;
    if (c_ob_done && m_state_OB_DONE && (m_rd && m_map && m_idx == 22)) m_set[4] = 1'b1;
    if (c_ob_done && m_state_OB_DONE && !(m_rd && m_map && m_idx == 22)) m_set[5] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_w[16] <= 32'h0;
      m_w[17] <= 32'h0;
      m_w[18] <= 32'h0;
      m_w[19] <= 32'h0;
      m_w[20] <= 32'h0;
      m_w[21] <= 32'h0;
      m_w[22] <= 32'h0;
      m_pulse_CMD <= 0;
      m_state_RX_REP <= 0;
      m_state_DOORBELL <= 0;
      m_state_OB_DONE <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h3F;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 10) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFF;
      if (m_wr && m_map && m_idx == 11) m_w[11] <= ((m_w[11] & ~m_be) | (PWDATA & m_be)) & 32'h3FF;
      if (m_wr && m_map && m_idx == 12) m_w[12] <= ((m_w[12] & ~m_be) | (PWDATA & m_be)) & 32'hFF;
      if (m_wr && m_map && m_idx == 13) m_w[13] <= ((m_w[13] & ~m_be) | (PWDATA & m_be)) & 32'h1FFFFFF;
      if (m_wr && m_map && m_idx == 14) m_w[14] <= ((m_w[14] & ~m_be) | (PWDATA & m_be)) & 32'hFFFF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 15) ? PWDATA & m_be & 32'hF : 0;
      if (c_rx_rep && (!m_state_RX_REP || (m_rd && m_map && m_idx == 19))) begin
        m_w[19] <= (32'(c_rx_why[2:0]) << 0) | (32'(c_rx_ftype[3:0]) << 3);
        m_state_RX_REP <= 1;
      end else if ((m_rd && m_map && m_idx == 19)) m_state_RX_REP <= 0;
      if (c_db_valid && (!m_state_DOORBELL || (m_rd && m_map && m_idx == 21))) begin
        m_w[20] <= (32'(c_db_info[15:0]) << 0) | (32'(c_db_tid[7:0]) << 16);
        m_w[21] <= (32'(c_db_src[15:0]) << 0);
        m_state_DOORBELL <= 1;
      end else if ((m_rd && m_map && m_idx == 21)) m_state_DOORBELL <= 0;
      if (c_ob_done && (!m_state_OB_DONE || (m_rd && m_map && m_idx == 22))) begin
        m_w[22] <= (32'(c_ob_status[3:0]) << 0);
        m_state_OB_DONE <= 1;
      end else if ((m_rd && m_map && m_idx == 22)) m_state_OB_DONE <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h52490100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_OB_DONE, m_state_DOORBELL, m_state_RX_REP});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return m_w[11];
      12: return m_w[12];
      13: return m_w[13];
      14: return m_w[14];
      15: return 0;
      16: return (32'(c_host_rdata) << 0);
      17: return (32'(c_base_id) << 0);
      18: return (32'(c_ob_busy) << 0) | (32'(c_busy) << 1);
      19: return m_w[19];
      20: return m_w[20];
      21: return m_w[21];
      22: return m_w[22];
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][5:0] & m_w[2][5:0]))
  `SVA_INV(a_core_cfg_dev_id_car, c_cfg_dev_id_car == m_w[5][31:0])
  `SVA_INV(a_core_cfg_dev_info_car, c_cfg_dev_info_car == m_w[6][31:0])
  `SVA_INV(a_core_cfg_asm_id_car, c_cfg_asm_id_car == m_w[7][31:0])
  `SVA_INV(a_core_cfg_asm_info_car, c_cfg_asm_info_car == m_w[8][31:0])
  `SVA_INV(a_core_cfg_pe_feat_car, c_cfg_pe_feat_car == m_w[9][31:0])
  `SVA_INV(a_core_cfg_base_id, c_cfg_base_id == m_w[10][23:0])
  `SVA_INV(a_core_host_addr, c_host_addr == m_w[11][9:0])
  `SVA_INV(a_core_host_wdata, c_host_wdata == m_w[12][7:0])
  `SVA_INV(a_core_ob_dest, c_ob_dest == m_w[13][15:0])
  `SVA_INV(a_core_ob_tid, c_ob_tid == m_w[13][23:16])
  `SVA_INV(a_core_ob_tt, c_ob_tt == m_w[13][24:24])
  `SVA_INV(a_core_ob_info, c_ob_info == m_w[14][15:0])
  `SVA_INV(a_core_id_load, c_id_load == m_pulse_CMD[0])
  `SVA_INV(a_core_host_wr, c_host_wr == m_pulse_CMD[1])
  `SVA_INV(a_core_host_rd, c_host_rd == m_pulse_CMD[2])
  `SVA_INV(a_core_ob_start, c_ob_start == m_pulse_CMD[3])
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_cfg_dev_id_car == 32'h0 && c_cfg_dev_info_car == 32'h0 && c_cfg_asm_id_car == 32'h0 && c_cfg_asm_info_car == 32'h0 && c_cfg_pe_feat_car == 32'h0 && c_cfg_base_id == 24'h0 && c_host_addr == 10'h0 && c_host_wdata == 8'h0 && c_ob_dest == 16'h0 && c_ob_tid == 8'h0 && c_ob_tt == 1'h0 && c_ob_info == 16'h0 && c_id_load == 1'h0 && c_host_wr == 1'h0 && c_host_rd == 1'h0 && c_ob_start == 1'h0)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_DEV_ID_CAR, m_rd && m_map && m_idx == 5)
  `FC(wr_DEV_ID_CAR, m_wr && m_map && m_idx == 5)
  `FC(rd_DEV_INFO_CAR, m_rd && m_map && m_idx == 6)
  `FC(wr_DEV_INFO_CAR, m_wr && m_map && m_idx == 6)
  `FC(rd_ASM_ID_CAR, m_rd && m_map && m_idx == 7)
  `FC(wr_ASM_ID_CAR, m_wr && m_map && m_idx == 7)
  `FC(rd_ASM_INFO_CAR, m_rd && m_map && m_idx == 8)
  `FC(wr_ASM_INFO_CAR, m_wr && m_map && m_idx == 8)
  `FC(rd_PE_FEAT_CAR, m_rd && m_map && m_idx == 9)
  `FC(wr_PE_FEAT_CAR, m_wr && m_map && m_idx == 9)
  `FC(rd_BASE_ID_CFG, m_rd && m_map && m_idx == 10)
  `FC(wr_BASE_ID_CFG, m_wr && m_map && m_idx == 10)
  `FC(rd_MEM_ADDR, m_rd && m_map && m_idx == 11)
  `FC(wr_MEM_ADDR, m_wr && m_map && m_idx == 11)
  `FC(rd_MEM_WDATA, m_rd && m_map && m_idx == 12)
  `FC(wr_MEM_WDATA, m_wr && m_map && m_idx == 12)
  `FC(rd_OB_CTRL, m_rd && m_map && m_idx == 13)
  `FC(wr_OB_CTRL, m_wr && m_map && m_idx == 13)
  `FC(rd_OB_INFO, m_rd && m_map && m_idx == 14)
  `FC(wr_OB_INFO, m_wr && m_map && m_idx == 14)
  `FC(rd_CMD, m_rd && m_map && m_idx == 15)
  `FC(wr_CMD, m_wr && m_map && m_idx == 15)
  `FC(rd_MEM_RDATA, m_rd && m_map && m_idx == 16)
  `FC(wr_MEM_RDATA, m_wr && m_map && m_idx == 16)
  `FC(rd_BASE_ID, m_rd && m_map && m_idx == 17)
  `FC(wr_BASE_ID, m_wr && m_map && m_idx == 17)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 18)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 18)
  `FC(rd_RX_REP, m_rd && m_map && m_idx == 19)
  `FC(wr_RX_REP, m_wr && m_map && m_idx == 19)
  `FC(rd_DOORBELL0, m_rd && m_map && m_idx == 20)
  `FC(wr_DOORBELL0, m_wr && m_map && m_idx == 20)
  `FC(rd_DOORBELL1, m_rd && m_map && m_idx == 21)
  `FC(wr_DOORBELL1, m_wr && m_map && m_idx == 21)
  `FC(rd_OB_DONE, m_rd && m_map && m_idx == 22)
  `FC(wr_OB_DONE, m_wr && m_map && m_idx == 22)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_RX_REP_AVAIL_set, m_set[0])
  `FC(irq_RX_REP_AVAIL_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_RX_REP_AVAIL_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_RX_REP_AVAIL_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_RX_REP_OVF_set, m_set[1])
  `FC(irq_RX_REP_OVF_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_RX_REP_OVF_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_RX_REP_OVF_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_DOORBELL_AVAIL_set, m_set[2])
  `FC(irq_DOORBELL_AVAIL_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_DOORBELL_AVAIL_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_DOORBELL_AVAIL_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_DOORBELL_OVF_set, m_set[3])
  `FC(irq_DOORBELL_OVF_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_DOORBELL_OVF_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_DOORBELL_OVF_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_OB_DONE_AVAIL_set, m_set[4])
  `FC(irq_OB_DONE_AVAIL_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_OB_DONE_AVAIL_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_OB_DONE_AVAIL_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(irq_OB_DONE_OVF_set, m_set[5])
  `FC(irq_OB_DONE_OVF_cleared, m_w[1][5] && m_wr && m_map && m_idx == 1 && PWDATA[5] && PSTRB[0])
  `FC(irq_OB_DONE_OVF_masked, m_w[1][5] && !m_w[2][5])
  `FC(irq_OB_DONE_OVF_drives_pin, m_w[1][5] && m_w[2][5] && irq)
  `FC(cmd_id_load, m_pulse_CMD[0])
  `FC(cmd_host_wr, m_pulse_CMD[1])
  `FC(cmd_host_rd, m_pulse_CMD[2])
  `FC(cmd_ob_start, m_pulse_CMD[3])
  `FC(RX_REP_capture, c_rx_rep && !m_state_RX_REP)
  `FC(RX_REP_overflow, c_rx_rep && m_state_RX_REP && !(m_rd && m_map && m_idx == 19))
  `FC(RX_REP_pop, m_rd && m_map && m_idx == 19 && m_state_RX_REP)
  `FC(RX_REP_read_empty, m_rd && m_map && m_idx == 19 && !m_state_RX_REP)
  `FC(RX_REP_pop_and_capture, c_rx_rep && m_state_RX_REP && m_rd && m_map && m_idx == 19)
  `FC(DOORBELL_capture, c_db_valid && !m_state_DOORBELL)
  `FC(DOORBELL_overflow, c_db_valid && m_state_DOORBELL && !(m_rd && m_map && m_idx == 21))
  `FC(DOORBELL_pop, m_rd && m_map && m_idx == 21 && m_state_DOORBELL)
  `FC(DOORBELL_read_empty, m_rd && m_map && m_idx == 21 && !m_state_DOORBELL)
  `FC(DOORBELL_pop_and_capture, c_db_valid && m_state_DOORBELL && m_rd && m_map && m_idx == 21)
  `FC(OB_DONE_capture, c_ob_done && !m_state_OB_DONE)
  `FC(OB_DONE_overflow, c_ob_done && m_state_OB_DONE && !(m_rd && m_map && m_idx == 22))
  `FC(OB_DONE_pop, m_rd && m_map && m_idx == 22 && m_state_OB_DONE)
  `FC(OB_DONE_read_empty, m_rd && m_map && m_idx == 22 && !m_state_OB_DONE)
  `FC(OB_DONE_pop_and_capture, c_ob_done && m_state_OB_DONE && m_rd && m_map && m_idx == 22)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind RAPIDIO_apb RAPIDIO_apb_sva u_apb_sva (.*);
